* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
.mi-wrap {
  height: calc(var(--appsmith-ui-height) * 1px);
  width: calc(var(--appsmith-ui-width) * 1px);
  overflow: auto;
  background: #1E293B;
  border: 1px solid #334155;
  border-radius: 6px;
  font-family: system-ui;
}
table.mi { border-collapse: collapse; width: max-content; min-width: 100%; background: #1E293B; }
table.mi th { padding: 10px 14px; font-size: 12px; font-weight: 700; color: #F1F5F9; white-space: nowrap; text-align: left; border-bottom: 2px solid #475569; background: #334155; position: sticky; top: 0; }
table.mi td { padding: 8px 14px; font-size: 12px; color: #E2E8F0; border-bottom: 1px solid #334155; vertical-align: top; }
table.mi td.fix { white-space: nowrap; }
table.mi td.yr { min-width: 240px; white-space: normal; }
.empty { padding: 20px; color: #94A3B8; text-align: center; font-family: system-ui; }

