function monthLabel(ym) {
  var m = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  return m[parseInt(ym.slice(5,7),10)-1] || ym;
}
function esc(s) {
  return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
function render(model) {
  var root = document.getElementById('root');
  if (!root) return;
  var rows = (model && model.rows) || [];
  var axis = (model && model.axis) || [];
  if (!rows.length || !axis.length) {
    root.innerHTML = '<div class="empty">No data available</div>';
    return;
  }
  // year groups in axis order (newest first)
  var groups = [];
  axis.forEach(function(ym){
    var y = ym.slice(0,4);
    var last = groups[groups.length-1];
    if (last && last.year === y) last.months.push(ym);
    else groups.push({ year: y, months: [ym] });
  });
  var h = '<table class="mi"><thead><tr>';
  ['Location','Billing ID','Vendor'].forEach(function(c){ h += '<th>' + c + '</th>'; });
  groups.forEach(function(g){ h += '<th>' + g.year + '</th>'; });
  h += '</tr></thead><tbody>';
  rows.forEach(function(r){
    var cover = r.cover || {};
    h += '<tr>';
    h += '<td class="fix">' + esc(r.location) + '</td>';
    h += '<td class="fix">' + esc(r.billingId) + '</td>';
    h += '<td class="fix">' + esc(r.vendor) + '</td>';
    groups.forEach(function(g){
      var parts = [];
      g.months.forEach(function(ym){
        var c = cover[ym];
        // list months that are MISSING or PARTIAL invoice data; fully-covered months are omitted
        if (c === 'full') return;                                  // fully covered -> not missing
        if (c === 'partial') parts.push(monthLabel(ym) + '*');     // partial coverage
        else parts.push(monthLabel(ym));                           // none -> fully missing
      });
      h += '<td class="yr">' + (parts.length ? parts.join(', ') : '—') + '</td>';
    });
    h += '</tr>';
  });
  h += '</tbody></table>';
  root.innerHTML = h;
}
appsmith.onReady(function(){
  render(appsmith.model);
  appsmith.onModelChange(function(m){ render(m); });
});

